parserpath=pathlib.Path('/home/t4ce/Repositories/TRUEOS/tools/codex_startup_report.py');spec=importlib.util.spec_from_file_location('startup_report',parserpath);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
lines=raw.decode('utf-8','replace').splitlines();report=m.parse_lines(lines)
allowed=set('vm gen id carrier stage age_ms seq phase role activity admission_ms ready_max_ms slice_max_ms park_max_ms overrun_max_ms abi abi_age_ms abi_since_ms abi_depth abi_entered abi_exited abi_seq abi_last abi_last_exit_ms'.split());progress=[];allocators=[];markers=[]
