  if row:allocators.append({'line':n,**row})
 match=m.ROW.search(l)
 if match:
  pid,elapsed,delta,stage=match.groups();name=stage.partition(' ')[0]
  if name in ['thread_attach_done','session_prompt_ready','startup_handoff_frame_rendered']:markers.append({'line':n,'name':name,'elapsed_ms':float(elapsed)})
apps=[]
