 apps.append({'context':run['context'],'runtime':run.get('runtime'),'placement':run.get('placement'),'startup_websocket_prewarm':run.get('startup_websocket_prewarm'),'startup_skills_coalescing':run.get('startup_skills_coalescing'),'startup_skills_refresh_coalesced':run.get('startup_skills_refresh_coalesced',False),'startup_prewarm_override_invalid':run.get('startup_prewarm_override_invalid',False),'startup_skills_override_invalid':run.get('startup_skills_override_invalid',False),'endpoints':{**run['endpoints'],'attach_done_ms':attach,'attach_to_ready_ms':None if attach is None or ready is None else ready-attach},'startup_app_events':run.get('startup_app_events',[]),'startup_server_events':run.get('startup_server_events',[]),'startup_handoff_states':run.get('startup_handoff_states',[]),'slow_spans':run['slow_spans'],'long_polls':run['long_polls'],'open_spans':run['open_spans'],'last_elapsed_ms':run['last_elapsed_ms']})
checks={'exactly_one_application':len(apps)==1,'archive_matches':bool(apps) and all(r['context'].get('archive_sha256')==a.expected_sha256 for r in apps)}
