#!/usr/bin/env python3
"""Temporarily set one worker limit for the agent's fresh launch, then restore dotenv."""
import argparse
import json
import subprocess
import sys
import urllib.request
import urllib.error

p=argparse.ArgumentParser();p.add_argument('--workers',type=int);p.add_argument('--prewarm',type=int,choices=(0,1));p.add_argument('--coalesce',type=int,choices=(0,1));p.add_argument('--name',required=True);p.add_argument('--no-input-seconds',type=float,default=5);a=p.parse_args()
if a.workers is not None and a.workers not in range(1,5): raise SystemExit('workers must be 1..4')
if a.workers is None and a.prewarm is None and a.coalesce is None: raise SystemExit('a worker, prewarm or coalescing control is required')
base='http://192.168.178.94'
path='/dl/2/apps/codex/.codex/.env'
def read():
    try:
        with urllib.request.urlopen(base+path,timeout=10) as r: b=r.read(65537)
        if len(b)>65536: raise RuntimeError('dotenv exceeds bounded control size')
        b.decode('utf-8')
        return b
    except urllib.error.HTTPError as e:
        if e.code==404: return None
        raise
def post(path,body=b''):
    with urllib.request.urlopen(urllib.request.Request(base+path,data=body,method='POST'),timeout=30) as r:
        if r.status!=200: raise RuntimeError('control write failed')
        r.read(4096)
original=read()
if original is not None: raise SystemExit('Existing dotenv preserved; controlled trial requires absent temporary dotenv')
settings=[]
if a.workers is not None: settings.append(f'TOKIO_WORKER_THREADS={a.workers}')
if a.prewarm is not None: settings.append(f'CDX_STARTUP_PREWARM={a.prewarm}')
if a.coalesce is not None: settings.append(f'CDX_STARTUP_SKILLS_COALESCE={a.coalesce}')
updated=('\n'+'\n'.join(settings)+'\n').encode()
restored=False
try:
    post('/up/2/apps/codex/.codex?name=.env&content=blob',updated)
    if read()!=updated: raise RuntimeError('worker control readback differs')
    subprocess.run([sys.executable,'/tmp/trueos-codex-startup-probe.py','--name',a.name,'--no-input-seconds',str(a.no_input_seconds)],check=True)
finally:
    restore_error=None
    try:
        current=read()
        if current==original:
            restored=True
        elif current==updated:
            if original is None: post('/rm/2/apps/codex/.codex/.env')
            else: post('/up/2/apps/codex/.codex?name=.env&content=blob',original)
            restored=read()==original
        else: restore_error='concurrent_change_preserved'
    except (OSError,urllib.error.URLError) as e:
        restore_error=type(e).__name__
    receipt={'worker_control':a.workers,'prewarm_control':a.prewarm,'coalesce_control':a.coalesce,'original_dotenv_existed':original is not None,'dotenv_restored':restored,'restore_error':restore_error,'temporary_assignments':settings}
    from pathlib import Path
    Path('/tmp/trueos-codex-'+a.name+'-control.json').write_text(json.dumps(receipt,indent=2)+'\n')
    print(json.dumps(receipt))
    if not restored: raise SystemExit('Temporary dotenv cleanup pending; unknown content was preserved')

